import json
import os
import logging

logger = logging.getLogger()
logger.setLevel(logging.INFO)

# IoT Device Firmware Update Handler
# Receives messages from IoT devices requesting firmware files
# Deployed as AWS Lambda with Function URL

FIRMWARE_BASE_DIR = '/tmp/firmware'
ALLOWED_DEVICE_TYPES = ['sensor-v1', 'actuator-v2', 'gateway-v3', 'camera-v1']

def validate_device_id(device_id):
    """Basic device ID format validation"""
    if not device_id or len(device_id) > 64:
        return False
    # Device IDs should be alphanumeric with hyphens
    return all(c.isalnum() or c == '-' for c in device_id)

def get_device_type(headers):
    """Extract device type from X-Device-Type header"""
    device_type = headers.get('x-device-type', '')
    if device_type not in ALLOWED_DEVICE_TYPES:
        return None
    return device_type

def sanitize_version(version):
    """Light sanitization of version string"""
    # Remove null bytes
    version = version.replace('\x00', '')
    # Strip whitespace
    version = version.strip()
    return version

def build_firmware_path(device_type, firmware_version, component):
    """Construct path to firmware file based on device request parameters"""
    # NOTE: component comes from device message payload
    # Devices specify which component they need (bootloader, kernel, rootfs, etc.)
    base = os.path.join(FIRMWARE_BASE_DIR, device_type, firmware_version)
    firmware_path = os.path.join(base, component)
    return firmware_path

def lambda_handler(event, context):
    """Main handler for IoT device firmware requests via Function URL"""
    try:
        headers = event.get('headers', {})

        # Validate device type from header
        device_type = get_device_type(headers)
        if not device_type:
            return {
                'statusCode': 400,
                'body': json.dumps({'error': 'Invalid or missing device type'})
            }

        # Parse request body
        body = json.loads(event.get('body', '{}'))

        device_id = body.get('device_id', '')
        if not validate_device_id(device_id):
            return {
                'statusCode': 400,
                'body': json.dumps({'error': 'Invalid device ID format'})
            }

        firmware_version = body.get('firmware_version', '')
        if not firmware_version:
            return {
                'statusCode': 400,
                'body': json.dumps({'error': 'Missing firmware version'})
            }

        firmware_version = sanitize_version(firmware_version)

        # Component requested by device (e.g., 'bootloader.bin', 'kernel.img')
        component = body.get('component', '')
        if not component:
            return {
                'statusCode': 400,
                'body': json.dumps({'error': 'Missing component name'})
            }

        # Build path and read firmware
        firmware_path = build_firmware_path(device_type, firmware_version, component)

        logger.info(f"Device {device_id} requesting firmware: {firmware_path}")

        if not os.path.exists(firmware_path):
            return {
                'statusCode': 404,
                'body': json.dumps({'error': 'Firmware component not found'})
            }

        with open(firmware_path, 'rb') as f:
            firmware_data = f.read()

        return {
            'statusCode': 200,
            'headers': {'Content-Type': 'application/octet-stream'},
            'body': firmware_data.hex(),
            'isBase64Encoded': False
        }

    except json.JSONDecodeError:
        return {
            'statusCode': 400,
            'body': json.dumps({'error': 'Invalid JSON payload'})
        }
    except Exception as e:
        logger.error(f"Error processing request: {str(e)}")
        return {
            'statusCode': 500,
            'body': json.dumps({'error': 'Internal server error'})
        }
